sys_script_include.script:
var GetUserProject = Class.create();
GetUserProject.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	// 根据用户查询所在项目
	getProjectByUser : function(){
		var userSysId = this.getParameter('sysparm_user');
		// 项目人员表
		var gr = new GlideRecord('x_1973840_leave_crop_mana');
		gr.addQuery('employe_id',userSysId);
		gr.setLimit(1);
		gr.query();
		if (gr.next()){
			return gr.project_id + ',' + gr.project_id.getDisplayValue();	
		}
		return '';

	},

    type: 'GetUserProject'
});
